18	func findFile(t *testing.T, ds []FileDiff, path string) FileDiff {
19		t.Helper()
20		for _, d := range ds {
21			if d.Path == path {
22				return d
23			}
24		}
25		t.Fatalf("no FileDiff for %s; got %d entries", path, len(ds))
26		return FileDiff{}
27	}
