29	func TestTextualAdded(t *testing.T) {
30		a := mkArchive(nil)
31		b := mkArchive(map[string]string{"new.tf": "x\n"})
32		ds := Textual(a, b)
33		d := findFile(t, ds, "new.tf")
34		if d.Status != StatusAdded {
35			t.Errorf("status = %v, want Added", d.Status)
36		}
37		if d.Adds != 1 || d.Dels != 0 {
38			t.Errorf("adds/dels = %d/%d", d.Adds, d.Dels)
39		}
40	}
