55	func TestTextualModified(t *testing.T) {
56		a := mkArchive(map[string]string{"m.tf": "alpha\nbeta\n"})
57		b := mkArchive(map[string]string{"m.tf": "alpha\nGAMMA\n"})
58		ds := Textual(a, b)
59		d := findFile(t, ds, "m.tf")
60		if d.Status != StatusModified {
61			t.Errorf("status = %v, want Modified", d.Status)
62		}
63		if !strings.Contains(d.Unified, "-beta") || !strings.Contains(d.Unified, "+GAMMA") {
64			t.Errorf("unified missing expected lines:\n%s", d.Unified)
65		}
66	}
