76	func TestTextualSortedByPath(t *testing.T) {
77		a := mkArchive(map[string]string{"z.tf": "a\n", "a.tf": "a\n"})
78		b := mkArchive(map[string]string{"z.tf": "b\n", "a.tf": "b\n"})
79		ds := Textual(a, b)
80		if len(ds) != 2 {
81			t.Fatalf("got %d diffs, want 2", len(ds))
82		}
83		if ds[0].Path != "a.tf" || ds[1].Path != "z.tf" {
84			t.Errorf("expected sorted by path; got %s, %s", ds[0].Path, ds[1].Path)
